#!/usr/bin/env python3
"""One-time finishing step.
  1. The memory governor writes every approved fact into the OWNING PROJECT'S documentation source (one setting on the
     write), and the worker is restarted.
  2. The documents that said otherwise are corrected.
  3. The mb-doc-check tests are saved, the docmap script is saved and the docmap rebuilt, and the project AGENTS.md
     files say that agents never use Git.
Every text change must match, or it is skipped and reported. Nothing is committed here."""
import base64, os, re, shutil, subprocess, sys

C = os.environ.get("FINISH_C", "/mnt/c")
GOV = os.environ.get("FINISH_GOV", "/home/dev-p/memory-governor")
CFG = f"{C}/mybizz/mybizz-config-docs"
OSD = f"{C}/mybizz/mybizz-os-docs"
SCR = f"{C}/mybizz/scripts"
TESTS = {'test_mb_doc_check.py': '', 'test_v3_abs.py': '', 'test_v3_cleanup.py': '', 'test_v3_eol.py': '', 'test_v3_frontmatter.py': '', 'test_v3_links.py': '', 'test_v3_paths.py': '', 'test_v3_tables.py': ''}
BUILD_DOCMAP = ""
RUNNER = '#!/usr/bin/env bash\n# Runs the mb-doc-check tests against the installed script.  Usage: bash run-tests.sh\nset -euo pipefail\nD="$(mktemp -d)"\ncp "$(dirname "$0")"/test_*.py "$D"/\ncp /mnt/c/mybizz/scripts/mb-doc-check.py "$D"/\ncd "$D" && python3 -W ignore -m unittest discover -p \'test_*.py\' 2>&1 | tail -4\n'
problems = 0

def say(s): print("   " + s)

# =============================================================== 1. the governor
print("1. The memory governor")
gp = f"{GOV}/app/gbrain.py"
try:
    src = open(gp, encoding="utf-8", newline="").read()
except OSError:
    say(f"NOT FOUND   {gp}"); src = None; problems += 1
if src is not None:
    if 'GBRAIN_SOURCE' in src:
        say("already done: the write names the owning project's source")
    else:
        old = "        capture_output=True, text=True, check=True,\n    )\n    return result.stdout.strip()"
        new = ("        # the fact is written into the owning project's own source, whatever folder the worker runs in\n"
               "        env={**os.environ, \"GBRAIN_SOURCE\": candidate.owning_project},\n"
               "        capture_output=True, text=True, check=True,\n    )\n    return result.stdout.strip()")
        if src.count(old) != 1:
            say("NOT CHANGED gbrain.py: the expected lines were not found exactly once"); problems += 1
        else:
            new_src = src.replace(old, new)
            if not re.search(r"^import os$", new_src, re.M):
                new_src = new_src.replace("import subprocess\n", "import os\nimport subprocess\n", 1)
            bdir = os.path.expanduser("~/backups"); os.makedirs(bdir, exist_ok=True)
            shutil.copy(gp, f"{bdir}/gbrain.py.before-source-fix")
            open(gp, "w", encoding="utf-8", newline="").write(new_src)
            r = subprocess.run([sys.executable, "-m", "py_compile", gp], capture_output=True, text=True)
            if r.returncode != 0:
                shutil.copy(f"{bdir}/gbrain.py.before-source-fix", gp)
                say("STOPPED: the changed file did not compile, the original was put back"); problems += 1
            else:
                say("gbrain.py changed (a copy of the original is in ~/backups/gbrain.py.before-source-fix)")
                if not os.environ.get("FINISH_SKIP_RESTART"):
                    subprocess.run(["systemctl", "--user", "restart", "memory-governor-worker"])
                    a = subprocess.run(["systemctl", "--user", "is-active", "memory-governor-worker", "memory-governor-api"], capture_output=True, text=True).stdout.split()
                    say("worker and API after the restart: " + ", ".join(a))
                    if a != ["active", "active"]:
                        say("WARNING: a service is not active. Paste this screen to Claude."); problems += 1

# =============================================================== 2. tests and docmap
print("\n2. Tests and docmap")
tdir = f"{CFG}/gbrain/tests"
os.makedirs(tdir, exist_ok=True)
for name, b64 in TESTS.items():
    open(f"{tdir}/{name}", "wb").write(base64.b64decode(b64))
open(f"{tdir}/run-tests.sh", "w", newline="\n").write(RUNNER)
say(f"tests saved: {len(TESTS)} files and run-tests.sh in mybizz-config-docs/gbrain/tests")
bp = f"{SCR}/build-docmap.py"
open(bp, "wb").write(base64.b64decode(BUILD_DOCMAP))
r = subprocess.run([sys.executable, bp, "--write", "--file", f"{C}/dev/dev-root/docmap.md"], capture_output=True, text=True)
say("docmap script saved; docmap rebuilt:")
print("\n".join("      | " + l for l in (r.stdout + r.stderr).splitlines()))

# =============================================================== 3. documents
print("\n3. Documents")
def patch(path, rx, rep, label, flags=re.S, key=None):
    global problems
    try:
        t = open(path, encoding="utf-8", newline="").read()
    except OSError:
        say(f"NOT FOUND   {os.path.basename(path)}"); problems += 1; return
    new, n = re.subn(rx, lambda m: rep, t, count=1, flags=flags)
    if n == 0:
        if key is not None:
            if key not in t: return                      # already done on an earlier run
        elif len(rep) >= 30 and rep[:50] in t:
            return
        say(f"NOT CHANGED {os.path.basename(path)}: {label}"); problems += 1; return
    open(path, "w", encoding="utf-8", newline="").write(new)
    say(f"changed     {os.path.basename(path)}: {label}")

LANDS = "the owning project's own documentation source"
G, S = f"{CFG}/memory-governor", f"{CFG}/mb-submit-memory"
# -- GBrain documents: recall reads the facts of one source
patch(f"{CFG}/gbrain/gbrain-explainer.md", r"\*\*Facts are stored per source\.\*\*.*?§5\.",
      "**Facts are stored per source.** `remember` writes into the source that the call selects, and `recall` reads the facts of that one source. The memory governor names " + LANDS + " on every write, so its facts sit with the documents they belong to (see the governor explainer, §5).", "facts per source")
patch(f"{CFG}/gbrain/gbrain-reference.md", r"`recall` reads it\. In 0\.59\.18\.0 a call whose source came from the current\s+folder or from the default also reads every federated source; `--source`,\s+`GBRAIN_SOURCE` or `source_id` read one source only\.",
      "`recall` reads the facts of that one source.", "recall reads one source")
patch(f"{CFG}/gbrain/gbrain-upgrade-checklist.md", r"`recall` reads facts from that source and from every federated source,\s+unless `source_id` is given\.",
      "`recall` reads the facts of that one source (`source_id` names another single source).", "recall reads one source")
patch(f"{CFG}/gbrain/gbrain-upgrade-checklist.md", r"- The governor's worker runs in `/home/dev-p/memory-governor`.*?stops every sync\.",
      "- The governor's worker names " + LANDS + " on every write (`GBRAIN_SOURCE` on the `gbrain remember` call), so governed facts land there. The worker also sets the brain default to the owning project before each write; a default that names a source that does not exist stops every sync.", "where governed facts land")
patch(f"{OSD}/os-reference-docs/memory-master-explainer.md", r"\*\*Facts are stored per source, and governed facts sit in one source\.\*\*.*?The remedy is an open developer decision\.",
      "**Facts are stored per source, and each governed fact goes to its owning project's source.** GBrain stores every fact in a source, and `recall` reads the facts of one source. The gate's worker names " + LANDS + " on every write, so a governed fact lands with the documents it belongs to (a federated source), and its fact file is a document that an ordinary search finds. Project isolation is enforced by the gate itself: every governed fact is stamped with its owning project, and visibility is mapped from declared scope. A governed fact written before 2026-10-01 may still sit in `memory-governor-code`.", "where governed facts land")
patch(f"{OSD}/os-reference-docs/memory-master-explainer.md", r" Whether governed facts should stay in `memory-governor-code`, given the recall gap\.", "", "open decision closed", key="given the recall gap")
# -- memory governor documents
patch(f"{G}/memory-governor-config.md", r"^\| Source switching \|[^\n]*$",
      "| Source switching | `gbrain sources default <owning_project>` before every write — fails loudly on an unknown source (the coupling defect guard). The write itself names the owning project's source (`GBRAIN_SOURCE` on the `gbrain remember` call), so the fact lands in that source whatever folder the worker runs in |", "source switching", flags=re.M)
patch(f"{G}/memory-governor-config.md", r"^\| Where governed facts land \|[^\n]*$",
      "| Where governed facts land | " + LANDS[0].upper() + LANDS[1:] + " (federated). A fact written before 2026-10-01 may still sit in `memory-governor-code` |", "where governed facts land", flags=re.M)
patch(f"{G}/memory-governor-config.md", r"^- \*\*Governed facts land in one source, `memory-governor-code`[^\n]*$",
      "- **Governed facts land in " + LANDS + "** (since 2026-10-01; before that they landed in `memory-governor-code`). A search from a documentation session sees them. The isolation between projects is enforced by the governor (entity stamping, visibility mapping, read-time resolution), not by GBrain's sources.", "governed facts land", flags=re.M)
patch(f"{G}/memory-governor-config.md", r"^6\. Decide where governed facts should live\.[^\n]*$",
      "6. Where governed facts live — decided 2026-10-01: in " + LANDS + ". The worker's `remember` call names it. Done.", "item 6", flags=re.M)
patch(f"{G}/memory-governor-reference.md", r"^Where governed facts land:[^\n]*$",
      "Where governed facts land: " + LANDS + ". The worker names that source on every `gbrain remember` call (`GBRAIN_SOURCE`), so the fact lands there whatever folder the worker runs in. A fact written before 2026-10-01 may still sit in `memory-governor-code`.", "where governed facts land", flags=re.M)
patch(f"{G}/memory-governor-reference.md", r" Open decision: see the configuration, Pending developer execution item 6\.", "", "open decision", key="Open decision: see the configuration")
patch(f"{G}/memory-governor-explainer.md", r"\*\*Correction 2026-09-30 — facts are stored per source, not brain-globally\.\*\*.*?recorded as an open decision in the configuration\.",
      "**Facts are stored per source.** Every fact belongs to a source, and `recall` reads the facts of one source. The worker names " + LANDS + " on every write, so a governed fact lands with the documents it belongs to, in a federated source, and an ordinary search finds its fact file. Isolation between projects is enforced by the governor itself (entity stamping, visibility mapping, read-time resolution); it does not come from GBrain's sources. A fact written before 2026-10-01 may still sit in `memory-governor-code`.", "facts per source")
patch(f"{G}/memory-governor-explainer.md", r"\*\*Governed facts are stored in one source, `memory-governor-code`\*\* —\s+covered in §5 \(corrected 2026-09-30\)\.",
      "**Governed facts are stored in the owning project's own source** — covered in §5.", "governed facts source")
# -- mb-submit-memory documents
patch(f"{S}/mb-submit-memory-config.md", r"Governed facts are stored in this source \(49 → 50 after the run of 2026-09-30\); it is not federated \|",
      "Facts written before 2026-10-01 may still sit in it; new governed facts go to the owning project's source |", "its own source")
patch(f"{S}/mb-submit-memory-config.md", r"^\| Where the fact landed \|[^\n]*$",
      "| Where the fact lands | The owning project's documentation source (the worker names it on every write since 2026-10-01). The run of 2026-09-30, before that change, landed in `memory-governor-code` |", "where the fact lands", flags=re.M)
patch(f"{S}/mb-submit-memory-config.md", r"^\| Recall gap \(reported by the skill in Step 4\) \|[^\n]*\n", "", "recall gap row", flags=re.M, key="Recall gap (reported by the skill")
patch(f"{S}/mb-submit-memory-config.md", r"^- Recall gap \(2026-09-30\):[^\n]*\n", "", "recall gap item", flags=re.M, key="- Recall gap (2026-09-30)")
patch(f"{S}/mb-submit-memory-reference.md", r"\n   \*\*Known recall gap \(2026-09-30\)\.\*\*.*?Then form:", " Then form:", "recall gap paragraph", key="Known recall gap (2026-09-30)")
patch(f"{S}/mb-submit-memory-reference.md", r"governed facts sit in `memory-governor-code`, which that search does not read \(Step 3\)\.",
      "`recall` reads the facts of one source, and a fact written before 2026-10-01 may sit in `memory-governor-code` (Step 3).", "do not")
patch(f"{S}/mb-submit-memory-explainer.md", r"And because GBrain ranks the worker's\s+own folder above that default, governed facts land in the source\s+`memory-governor-code`, not in the project's source\.",
      "The write itself names the owning project's source, so the fact lands there whatever folder the worker runs in.", "coupling")
patch(f"{S}/mb-submit-memory-explainer.md", r"\*\*Why a search for related facts can come back empty \(2026-09-30\)\.\*\*.*?\(configuration, open items\)\.\n\n", "", "empty search paragraph", key="Why a search for related facts can come back empty")
patch(f"{S}/mb-submit-memory-explainer.md", r"the recall gap\s+above awaits a developer decision; and", "and", "open questions", key="above awaits a developer decision")
patch(f"{S}/mb-submit-memory-explainer.md", r"the detect step cannot see governed facts \(recall gap, 2026-09-30\);\s+", "", "weakness", key="recall gap, 2026-09-30")
# -- facts procedure
patch(f"{OSD}/operating-procedures/fact-save-and-recall.md", r"Governed facts are stored in their own GBrain source.*?finds it\.",
      "Every governed fact is saved into the documentation of its own project and also exists as a fact file there, so an ordinary GBrain search finds it.", "governed facts are found by search")
# -- mb-doc-check documents: the tests are stored
D = f"{CFG}/mb-doc-check"
patch(f"{D}/doc-check-config.md", r"\| Tests \| 143 automated tests \(Python `unittest`\) \|", "| Tests | 143 automated tests (Python `unittest`), stored in `mybizz-config-docs\\gbrain\\tests` and run with `bash /mnt/c/mybizz/mybizz-config-docs/gbrain/tests/run-tests.sh` |", "tests location")
patch(f"{D}/doc-check-config.md", r"\| 1 \| The automated tests are not stored on this computer \| Open \|\n", "", "open item closed", key="The automated tests are not stored on this computer")
patch(f"{D}/doc-check-config.md", r"\| 2 \| The two dormant libraries", "| 1 | The two dormant libraries", "renumber")
patch(f"{D}/doc-check-config.md", r"\| 3 \| The program's built-in", "| 2 | The program's built-in", "renumber", key="| 3 | The program's built-in")
patch(f"{D}/doc-check-explainer.md", r" The automated tests are not yet stored on this computer\.", "", "tests are stored", key="The automated tests are not yet stored on this computer")
# -- project AGENTS.md files
GIT = "- Git: agents never commit, push, reset, rebase, change branches or force-pull. There is no grant for Git. The developer runs `commit-all.sh`."
for p in (f"{C}/pdlf/AGENTS.md", f"{C}/dev/dev-mb-3-cs/mb-3-cs-project-library/AGENTS.md"):
    if os.path.exists(p):
        patch(p, r"^- Git operations are permission-only:[^\n]*(?:\n  [^\n]*)*", GIT, "agents never use Git", flags=re.M)

print("\n" + ("Some changes did not match (listed above). Paste this screen to Claude." if problems else "All done."))
sys.exit(1 if problems else 0)
